def allowed(portfolio, funded) -> bool:
    """Does a plan keep every rule of the selection model? Checked by hand, not by a solver."""
    chosen = set(funded)
    if sum(portfolio.project(pid).capex for pid in chosen) > portfolio.capital_budget:
        return False

